<!doctype html><html lang="en"><head><meta charset="utf-8"><style>@page{margin:35px}body{font-family:"DejaVu Sans",sans-serif;color:#141715;font-size:10px}h1{color:#173dc6;font-size:30px;margin:0}h2{font-size:18px}p{line-height:1.6}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{padding:9px;border:1px solid #ddd;text-align:left;vertical-align:top}th{background:#edf0fb}thead{display:table-header-group}tr{page-break-inside:avoid}.meta{color:#666}.note{padding:10px;background:#fff4c7}.total{text-align:right;font-size:14px}</style></head><body><h1>minitz.</h1><h2>{{ ['order'=>'Order summary','customers'=>'Customer report','sales'=>'Sales report'][$type] }}</h2><p class="meta">Generated {{ now()->format('d M Y H:i') }} IST · Internal business record</p>@if($type==='order')@php $order=$orders->first(); @endphp<p><strong>MZ-{{ str_pad($order->id,5,'0',STR_PAD_LEFT) }}</strong><br>{{ $order->name }}<br>{{ $order->email }} · {{ $order->phone }}<br>{{ $order->address }}</p><p>Status: {{ str_replace('_',' ',$order->status) }}</p>@if($order->status==='preview')<p class="note">PREVIEW ORDER — No payment collected. No delivery booked.</p>@endif<table><thead><tr><th>Product</th><th>Pack</th><th>Qty</th><th>Unit price INR</th><th>Total INR</th></tr></thead><tbody>@foreach(json_decode($order->items) as $item)<tr><td>{{ $item->name }}</td><td>{{ $item->weight }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->price/100,2) }}</td><td>{{ number_format($item->price*$item->quantity/100,2) }}</td></tr>@endforeach</tbody></table><p class="total">Subtotal INR {{ number_format($order->subtotal/100,2) }}<br>Delivery INR {{ number_format($order->shipping/100,2) }}<br><strong>Total INR {{ number_format($order->total/100,2) }}</strong></p><p class="meta">Order summary only. This document is not a tax invoice.</p>@else<table><thead><tr><th>Order</th><th>Customer</th><th>Email</th>@if($type==='customers')<th>Phone and address</th>@else<th>Total INR</th><th>Status</th>@endif<th>Date</th></tr></thead><tbody>@forelse($orders as $order)<tr><td>MZ-{{ str_pad($order->id,5,'0',STR_PAD_LEFT) }}</td><td>{{ $order->name }}</td><td>{{ $order->email }}</td>@if($type==='customers')<td>{{ $order->phone }}<br>{{ $order->address }}</td>@else<td>{{ number_format($order->total/100,2) }}</td><td>{{ str_replace('_',' ',$order->status) }}</td>@endif<td>{{ substr($order->created_at,0,10) }}</td></tr>@empty<tr><td colspan="6">No records in the selected date range.</td></tr>@endforelse</tbody></table>@if($type==='sales')<p><strong>Verified sales total INR {{ number_format($orders->whereIn('status',['paid','processing','shipped','delivered'])->sum('total')/100,2) }}</strong></p><p>Preview, pending and cancelled orders are excluded from the verified sales total.</p>@endif @endif</body></html>
